def classify_existing(apps, schema_editor):
    """Inventory only: label existing recognised text by the engine that produced it. Nothing is re-processed."""
    Version = apps.get_model("library", "DocumentVersion")
    DocumentType = apps.get_model("library", "DocumentType")
    for v in Version.objects.filter(ocr_applied=True).only("id", "ocr_quality").iterator():
        engine = str((v.ocr_quality or {}).get("engine") or "")
        label = "tesseract" if engine in ("tesseract", "ocrmypdf") else "unknown"
        Version.objects.filter(pk=v.pk).update(ocr_engine=label, ocr_model="Tesseract (ocrmypdf)" if engine == "ocrmypdf"
                                               else ("Tesseract" if label == "tesseract" else ""))
    # Document types keep their Tesseract languages for Legacy runs and get the matching PP-OCRv5 profile.
    for t in DocumentType.objects.all():
        langs = set(t.ocr_languages or [])
        profile = ("ar_en" if "ara" in langs else "hi_en" if "hin" in langs else "te_en" if "tel" in langs
                   else "ta_en" if "tam" in langs else "")
        if profile and not t.ocr_profile:
            DocumentType.objects.filter(pk=t.pk).update(ocr_profile=profile)


Migration.operations.append(migrations.RunPython(classify_existing, migrations.RunPython.noop))
